#!/usr/bin/env -S uv run --script
# Synced from bootstrap: repo/tools/mise/tasks/test-e2e.py. Do not edit this file.
# The next sync writes it again, and each change in this file is lost.
# /// script
# requires-python = ">=3.14"
# dependencies = []
# ///
# MISE description="Run the end-to-end tests: each test:e2e part"
# MISE tools={uv="latest", python="3.14"}

# USAGE arg "[args]" var=#true help="the arguments and flags for each part, unchanged"

import os
import subprocess
import sys

sys.dont_write_bytecode = True
sys.path.insert(0, f"{os.environ['MISE_PROJECT_ROOT']}/.config/mise/tasks/_scripts")
import helpers  # noqa: E402


def main():
  # The parts: each test:e2e:NN-<name> task, from a tool or from this
  # repository, in the order of its number. Each gets the raw arguments, with
  # their quoting, so an undeclared flag of a part (--update) needs no --.
  parts = helpers.own_tasks("test:e2e")
  if not parts:
    helpers.print_info("No test:e2e part in this repository")
    sys.exit(0)
  for task in parts:
    rc = subprocess.run(["mise", "run", task, *sys.argv[1:]], check=False).returncode
    if rc:
      sys.exit(128 - rc if rc < 0 else rc)
  helpers.print_success("End-to-end testing done")


if __name__ == "__main__":
  main()
